<script lang="ts">
  import { IdMap, Ref, Status } from '@hcengineering/core'
  import { getClient } from '@hcengineering/presentation'
  import task, { ProjectType } from '@hcengineering/task'
  import { selectedTaskTypeStore, typeStore } from '@hcengineering/task-resources'
  import { IssueStatus, Project } from '@hcengineering/tracker'
  import { statusStore } from '@hcengineering/view-resources'
  import StatusPresenter from './StatusPresenter.svelte'
  import StatusSelector from './StatusSelector.svelte'

  export let value: Ref<Status> | undefined
  export let space: Ref<Project>
  export let onChange: ((value: Ref<Status>) => void) | undefined = undefined
  export let size: 'small' | 'medium' = 'medium'
  export let kind: 'list-header' | undefined = undefined
  export let colorInherit: boolean = false
  export let accent: boolean = false
  export let disabled: boolean = false

  $: statusValue = value ? $statusStore.byId.get(value) : undefined

  const client = getClient()
  let projectType: Ref<ProjectType> | undefined = undefined

  $: if (onChange !== undefined) void getProjectType(space, $typeStore)

  async function getProjectType (spaceId: Ref<Project> | undefined, types: IdMap<ProjectType>): Promise<void> {
    if (spaceId === undefined) {
      projectType = undefined
      return
    }
    const _space = await client.findOne(task.class.Project, { _id: spaceId })
    projectType = _space !== undefined ? types.get(_space.type)?._id : undefined
  }
  $: issueStatusValue = value as Ref<IssueStatus> | undefined
</script>

{#if onChange !== undefined && value !== undefined && projectType !== undefined && issueStatusValue !== undefined}
  <StatusSelector
    value={issueStatusValue}
    type={projectType}
    taskType={$selectedTaskTypeStore}
    {size}
    kind={'link'}
    isEditable={!disabled}
    on:change={(e) => {
      if (onChange !== undefined) {
        onChange(e.detail)
      }
    }}
  />
{:else}
  <StatusPresenter
    {space}
    value={statusValue}
    {size}
    {kind}
    {colorInherit}
    {accent}
    on:accent-color
    taskType={$selectedTaskTypeStore}
  />
{/if}
