<script lang="ts">
  import { DocumentQuery, Ref } from '@hcengineering/core'
  import type { Asset, IntlString } from '@hcengineering/platform'
  import { createQuery } from '@hcengineering/presentation'
  import { Issue, IssueStatus, Project } from '@hcengineering/tracker'
  import { IModeSelector, resolvedLocationStore } from '@hcengineering/ui'
  import view, { Viewlet } from '@hcengineering/view'
  import { createEventDispatcher } from 'svelte'
  import { NavigatorModel } from '@hcengineering/workbench'

  import { TypeSelector, selectedTaskTypeStore, selectedTypeStore, taskTypeStore } from '@hcengineering/task-resources'
  import { filterStore } from '@hcengineering/view-resources'
  import tracker from '../../plugin'
  import IssuesView from './IssuesView.svelte'
  import ProjectSpaceLayout from '../projects/ProjectSpaceLayout.svelte'

  import task from '@hcengineering/task'

  export let currentSpace: Ref<Project> | undefined = undefined
  export let model: NavigatorModel | undefined = undefined
  export let baseQuery: DocumentQuery<Issue> = {}
  export let title: IntlString
  export let icon: Asset | undefined = undefined
  export let config: [string, IntlString, object][]
  export let allProjectsTypes: boolean = false
  export let useLocalMode: boolean = false
  export let spaceSelectorQuery: DocumentQuery<Project> | undefined = undefined
  export let autoSelectSpace: boolean = false

  export let baseClass = tracker.class.Issue

  const dispatch = createEventDispatcher()

  let query: DocumentQuery<Issue> | undefined = undefined
  let modeSelectorProps: IModeSelector | undefined = undefined

  $: spaceQuery = currentSpace !== undefined ? { space: currentSpace } : {}

  $: all = { ...baseQuery, ...spaceQuery }

  const activeStatusQuery = createQuery()

  let activeStatuses: Ref<IssueStatus>[] = []

  $: activeStatusQuery.query(
    tracker.class.IssueStatus,
    { category: { $in: [task.statusCategory.Active, task.statusCategory.ToDo] } },
    (result) => {
      activeStatuses = result.map(({ _id }) => _id)
    }
  )

  let active: DocumentQuery<Issue>
  $: active = { ...baseQuery, status: { $in: activeStatuses }, ...spaceQuery }

  const backlogStatusQuery = createQuery()

  let backlogStatuses: Ref<IssueStatus>[] = []
  let backlog: DocumentQuery<Issue> = {}
  $: backlogStatusQuery.query(tracker.class.IssueStatus, { category: task.statusCategory.UnStarted }, (result) => {
    backlogStatuses = result.map(({ _id }) => _id)
  })
  $: backlog = { ...baseQuery, status: { $in: backlogStatuses }, ...spaceQuery }

  $: queries = { all, active, backlog }
  $: urlMode = $resolvedLocationStore.query?.mode ?? undefined
  let mode: string | undefined
  $: if (!useLocalMode) {
    mode = urlMode
  }
  $: if (mode === undefined || (queries as any)[mode] === undefined) {
    ;[[mode]] = config
  }
  // ModeSelector ↔ Status-Filter conflict resolution. When the user has an
  // explicit Status filter active (via FilterButton/InlineFilterChips), the
  // ModeSelector greys out + shows a tooltip — status is now controlled by
  // the filter chip rather than the All/Active/Backlog shortcut. Re-enables
  // automatically when the status-filter is removed.
  $: hasStatusFilter = $filterStore.some((f) => f.key.key === 'status')

  // Reset the mode to 'all' on the RISING edge of hasStatusFilter
  // so a "Status is Backlog" filter added while in Active mode doesn't leave
  // the ModeSelector greyed-out with a stale "Active" highlight that lies
  // about what is actually filtered. Falling-edge does nothing — the user's
  // last explicit mode is preserved when the filter is removed.
  let lastHadStatusFilter = false
  $: {
    if (hasStatusFilter && !lastHadStatusFilter && mode !== 'all') {
      if (useLocalMode) {
        mode = 'all'
      } else {
        dispatch('action', { mode: 'all' })
      }
    }
    lastHadStatusFilter = hasStatusFilter
  }

  $: if (mode !== undefined) {
    query = { ...(queries as any)[mode] }
    modeSelectorProps = {
      config,
      mode,
      onChange: (newMode: string) => {
        if (useLocalMode) {
          mode = newMode
        } else {
          dispatch('action', { mode: newMode })
        }
      },
      disabled: hasStatusFilter,
      disabledReason: tracker.string.ModeSelectorDisabledByFilter
    }
  }

  $: allTypes = Array.from($taskTypeStore.values())
    .filter((it) => it.parent === $selectedTypeStore)
    .map((it) => it._id)

  $: finalQuery = {
    ...query,
    ...(allProjectsTypes
      ? {}
      : $selectedTaskTypeStore !== undefined
        ? { kind: $selectedTaskTypeStore }
        : { kind: { $in: allTypes } })
  }

  const toVL = (data: any): Viewlet | undefined => data as Viewlet
</script>

{#if query !== undefined && modeSelectorProps !== undefined}
  {#if currentSpace !== undefined}
    <ProjectSpaceLayout {currentSpace} {model}>
      <IssuesView
        query={finalQuery}
        space={currentSpace}
        {icon}
        {title}
        {modeSelectorProps}
        {spaceSelectorQuery}
        {autoSelectSpace}
      >
        <svelte:fragment slot="type_selector" let:viewlet>
          {#if !allProjectsTypes}
            <TypeSelector {baseClass} project={currentSpace} allTypes={toVL(viewlet)?.descriptor === view.viewlet.List} />
          {/if}
        </svelte:fragment>
      </IssuesView>
    </ProjectSpaceLayout>
  {:else}
    <IssuesView
      query={finalQuery}
      space={currentSpace}
      {icon}
      {title}
      {modeSelectorProps}
      {spaceSelectorQuery}
      {autoSelectSpace}
    >
      <svelte:fragment slot="type_selector" let:viewlet>
        {#if !allProjectsTypes}
          <TypeSelector {baseClass} project={currentSpace} allTypes={toVL(viewlet)?.descriptor === view.viewlet.List} />
        {/if}
      </svelte:fragment>
    </IssuesView>
  {/if}
{/if}
